    libs: [
        // TODO(202212484): The following two allow car-builtin-lib access to @hide Bluetooth APIs
        "framework-bluetooth.impl",
        "framework",
    ],

    stub_only_libs: [
        "framework-bluetooth",
    ],

    test: {
        enabled: false,
    },
    system: {
        enabled: true,
        sdk_version: "module_current",
    },
    module_lib: {
        enabled: true,
        sdk_version: "module_current",
    },

