package com.cockpitbench.systemfacade;
import android.content.Context;
import android.os.Bundle;
import android.os.RemoteCallbackList;
import android.os.RemoteException;
public final class SystemServiceFacade extends ISystemServiceFacade.Stub {
    public static final String SERVICE_NAME = "system_service_facade";
    private static final String PERMISSION = "android.car.permission.CAR_VENDOR_EXTENSION";
    private static final RemoteCallbackList<ISystemFacadeListener> LISTENERS = new RemoteCallbackList<>();
    private final Context context;
    private final ReflectionDispatcher dispatcher = new ReflectionDispatcher();
    public SystemServiceFacade(Context context, Object property, Object audio, Object power, Object user) {
        this.context = context;
        FacadeState.SERVICES.put("property", property);
        FacadeState.SERVICES.put("audio", audio);
        FacadeState.SERVICES.put("power", power);
        FacadeState.SERVICES.put("user", user);
    }
    @Override public Bundle transact(String service, String operation, Bundle arguments) {
        context.enforceCallingOrSelfPermission(PERMISSION, "system facade access");
        Bundle output = dispatcher.dispatch(service, operation, arguments == null ? new Bundle() : arguments);
        publish(service, operation, output);
        if ("power".equals(service) && "suspend".equals(operation)) {
            for (String dependent : new String[] {"audio", "user", "property"}) {
                try { dispatcher.dispatch(dependent, "prepareSuspend", arguments); } catch (Exception ignored) {}
            }
        }
        return output;
    }
    @Override public void registerListener(ISystemFacadeListener listener) { LISTENERS.register(listener); }
    @Override public void unregisterListener(ISystemFacadeListener listener) { LISTENERS.unregister(listener); }
    private static void publish(String service, String event, Bundle data) {
        int count = LISTENERS.beginBroadcast();
        try { for (int i = 0; i < count; i++) try {
            LISTENERS.getBroadcastItem(i).onEvent(service, event, data);
        } catch (RemoteException ignored) {} } finally { LISTENERS.finishBroadcast(); }
    }
}
