package com.cockpitbench.systemfacade;
import android.os.Bundle;
public final class ReflectionDispatcher {
    public Bundle dispatch(String service, String operation, Bundle arguments) {
        Bundle output = new Bundle();
        Object target = FacadeState.SERVICES.get(service);
        try {
            String platform = System.getProperty("ro.boot.soc_model", "8155").contains("8295")
                    ? "8295" : "8155";
            String type = Character.toUpperCase(service.charAt(0)) + service.substring(1);
            String className = "com.cockpitbench.systemfacade.platform" + platform
                    + "." + type + "Endpoint";
            ServiceEndpoint endpoint = (ServiceEndpoint) Class.forName(className)
                    .getDeclaredConstructor().newInstance();
            output = endpoint.invoke(target, operation, arguments);
        } catch (Exception ignored) {
            output.putBoolean("ok", false);
            output.putString("value", arguments.getString("fallback", ""));
        }
        FacadeState.CACHE.put(service, output);
        FacadeState.EVENTS.add(service + ":" + operation);
        return output;
    }
}
